// ===== START / STOP =====
const run = msg.payload;

function status(txt){ node.send([null,null,null,{payload:txt}]); }

// STOP: expliciete harde reset van alle outputs
if (run === false) {
  context.set('running', false);
  const cd = context.get('cd'); if (cd) clearInterval(cd);

  node.send([
    { payload: { outputs: { oranje_vlag: 0 } } },
    { payload: { outputs: { hoorn: 0 } } },
    { payload: { outputs: { piezo: 0 } } },
    { payload: 'STOP' }
  ]);
  return null;
}

// Start alleen bij true en voorkom dubbel starten
if (run !== true || context.get('running')) return null;
context.set('running', true);

// ===== CONFIG =====
const ORANGE_TIME = 20 * 1000;
const T5 = 5 * 60 * 1000;
const T4 = 4 * 60 * 1000;
const T1 = 1 * 60 * 1000;
const PIEZO_BEFORE = 10 * 1000;

const HORN_SHORT = 500;
const HORN_LONG  = 2000;

// ===== HELPERS =====
function horn(ms,label){
  status(`HOORN – ${label}`);
  node.send([null,{payload:{outputs:{hoorn:1}}},null,null]);
  setTimeout(()=>{
    if (!context.get('running')) return;
    node.send([null,{payload:{outputs:{hoorn:0}}},null,null]);
  }, ms);
}
function piezo(on){ node.send([null,null,{payload:{outputs:{piezo:on?1:0}}},null]); }

// ===== INIT-RESET BIJ START ON (essentieel!) =====
piezo(false); // expliciete reset zodat DO nooit blijft hangen
status('START ON – INIT RESET PIEZO');

// ===== ORANJE VLAG =====
node.send([{payload:{outputs:{oranje_vlag:1}}},null,null,null]);
status('ORANJE VLAG OP');

setTimeout(()=>{
  if (!context.get('running')) return;
  node.send([{payload:{outputs:{oranje_vlag:0}}},null,null,null]);
  horn(HORN_SHORT,'VLAG AF (EENMALIG)');
  startClass();
}, ORANGE_TIME);

// ===== KLASSE CYCLE =====
function startClass(){
  let cls = (context.get('cls')||0)+1; context.set('cls',cls);
  status(`START KLASSE ${cls}`);

  const startAt = Date.now()+T5;
  const cd = setInterval(()=>{
    if (!context.get('running')) return clearInterval(cd);
    const s = Math.max(0,Math.round((startAt-Date.now())/1000));
    status(`KLASSE ${cls} – START OVER ${s}s`);
  },10000);
  context.set('cd',cd);

  setTimeout(()=>{ if(context.get('running')) horn(HORN_SHORT,'4 MIN'); }, T5-T4);
  setTimeout(()=>{ if(context.get('running')) horn(HORN_SHORT,'1 MIN'); }, T5-T1);
  setTimeout(()=>{ if(context.get('running')) piezo(true); }, T5-PIEZO_BEFORE);

  setTimeout(()=>{
    if (!context.get('running')) return;
    clearInterval(cd);
    piezo(false);
    horn(HORN_LONG,'START');
    startClass();
  },T5);
}

return null;

const ON=250, OFF=750;
let t=context.get('t')||null, a=context.get('a')||false;
const v=msg?.payload?.outputs?.piezo;
function send(x){node.send({payload:{outputs:{piezo:x}}});}
function stop(){context.set('a',false); if(t){clearTimeout(t); t=null; context.set('t',null);} send(0);} 
if(v===1 && !a){a=true; context.set('a',true); (function loop(){ if(!context.get('a')) return; send(1); t=setTimeout(()=>{ send(0); t=setTimeout(loop,OFF); context.set('t',t); },ON); context.set('t',t); })();}
if(v===0){ stop(); }
return null;
